const sessionId = body.id || body.session_id || body.user_id || 'default';
const email = body.email || body.user_email;
const outputFormat = body.format || 'csv'; // 'csv' or 'text'

// Detect analysis type from message
const msg = message.toLowerCase();
let analysisType = 'query';
if (msg.includes('probabilidad') || msg.includes('mensual')) analysisType = 'monthly_probability';
if (msg.includes('excedencia') || msg.includes('frecuencia')) analysisType = 'exceedance_frequency';
if (msg.includes('duracion') || msg.includes('persistencia')) analysisType = 'duration_curve';
if (msg.includes('completo') || msg.includes('todo')) analysisType = 'complete';

// Detect station
let stationId = null;
let stationName = null;
if (msg.includes('calamar')) { stationId = '011375ab-c1be-4fa4-aa97-be2f39483b34'; stationName = 'Calamar'; }
