// Build text summary from results
const data = $input.all()[0].json;
const input = $('Parse Input').item.json;

if (!data || data.length === 0) {
  return [{ json: { summary: 'No se encontraron datos para la consulta.' } }];
}

const rows = Array.isArray(data) ? data : [data];
const analysisType = input.analysis_type;
let summary = '';

if (analysisType === 'monthly_probability') {
  summary = `Análisis de Probabilidad Mensual - ${input.station_name}\n\n`;
  summary += 'Mes | Registros | Promedio (m) | P10 | P50 | P90\n';
  summary += '----|-----------|--------------|-----|-----|-----\n';
  for (const row of rows.slice(0, 6)) {
    summary += `${row.mes_nombre} | ${row.registros} | ${row.promedio_m} | ${row.p10_m} | ${row.p50_m} | ${row.p90_m}\n`;
  }
} else if (analysisType === 'exceedance_frequency') {
  summary = `Curva de Frecuencia de Excedencia - ${input.station_name}\n\n`;
  summary += 'Prob. Excedencia | Nivel (m) | Clasificación\n';
  summary += '------------------|-----------|---------------\n';
  for (const row of rows) {
    summary += `${row.prob_excedencia}% | ${row.nivel_m} | ${row.clasificacion}\n`;
  }
} else if (analysisType === 'duration_curve') {
  summary = `Curva de Duración - ${input.station_name}\n\n`;
  summary += 'Duración (%) | Nivel (m) | Días/año | Clasificación\n';
  summary += '-------------|-----------|----------|---------------\n';
  for (const row of rows) {
    summary += `${row.duracion_percentil}% | ${row.nivel_m} | ${row.dias_por_año} | ${row.clasificacion}\n`;
  }
} else {
  summary = `Datos de nivel - ${input.station_name}\n\n`;
  summary += 'Fecha | Nivel (m)\n';
  summary += '------|----------\n';
  for (const row of rows.slice(0, 10)) {
    summary += `${row.fecha} | ${row.nivel_m}\n`;
  }
}

return [{ json: { summary: summary, row_count: rows.length } }];
